//! Concrete add I/O steps invoked from the add orchestration in
//! `core-node-internal`. Lives here so add-phase I/O primitives sit next to
//! the entity state they populate ([`super::entity::NodeStage::Added`],
//! `pending_working_dir`).

use std::path::{Path, PathBuf};

use daemon_config::consts::PEPPY_OUTPUT_DIR;
use tracing::debug;

/// Directories excluded from node snapshot copies.
///
/// These are either regenerated by the daemon (`.peppy`) or by the node's
/// `build_cmd` (virtual-environment / package directories). Copying virtual
/// environments breaks Python on macOS because `std::fs::copy` dereferences
/// symlinks, turning `@executable_path`-relative dylib references into
/// dangling paths.
const COPY_EXCLUDED_DIRS_PEPPY: &[&str] = &[".peppy"];

const COPY_EXCLUDED_DIRS_PYTHON: &[&str] = &[
    ".venv",
    ".pixi",
    "__pypackages__",
    "__pycache__",
    ".tox",
    ".nox",
    ".conda",
    ".mypy_cache",
    ".pytest_cache",
    ".ruff_cache",
];

const COPY_EXCLUDED_DIRS_RUST: &[&str] = &["target"];

const COPY_EXCLUDED_DIRS_JS_TS: &[&str] = &[
    "node_modules",
    ".next",
    ".nuxt",
    ".turbo",
    ".parcel-cache",
    ".svelte-kit",
    "bower_components",
];

const COPY_EXCLUDED_DIRS_C: &[&str] = &["build", "cmake-build-debug", "cmake-build-release"];

const COPY_EXCLUDED_DIRS_CPP: &[&str] = &[
    "build",
    "cmake-build-debug",
    "cmake-build-release",
    ".cache",
];

const COPY_EXCLUDED_DIRS_VCS: &[&str] = &[".git"];

const COPY_EXCLUDED_DIRS: &[&[&str]] = &[
    COPY_EXCLUDED_DIRS_PEPPY,
    COPY_EXCLUDED_DIRS_PYTHON,
    COPY_EXCLUDED_DIRS_RUST,
    COPY_EXCLUDED_DIRS_JS_TS,
    COPY_EXCLUDED_DIRS_C,
    COPY_EXCLUDED_DIRS_CPP,
    COPY_EXCLUDED_DIRS_VCS,
];

fn is_excluded_dir(name: &std::ffi::OsStr) -> bool {
    COPY_EXCLUDED_DIRS
        .iter()
        .any(|list| list.iter().any(|&excluded| name == excluded))
}

/// Recursively copies `src` into `dest`, skipping excluded directories.
///
/// Returns the names of top-level excluded directories that were present
/// directly under `src`. Nested skips are not recorded.
fn copy_dir_recursive(src: &Path, dest: &Path) -> std::io::Result<Vec<String>> {
    std::fs::create_dir_all(dest)?;

    let mut excluded = Vec::new();

    for entry in std::fs::read_dir(src)? {
        let entry = entry?;
        let file_name = entry.file_name();

        if is_excluded_dir(&file_name) {
            if let Some(name) = file_name.to_str() {
                excluded.push(name.to_owned());
            }
            continue;
        }

        let src_path = entry.path();
        let dest_path = dest.join(file_name);
        let ft = entry.file_type()?;

        // Skip symlinks to avoid infinite recursion with circular links
        if ft.is_symlink() {
            continue;
        }
        if ft.is_dir() {
            copy_dir_recursive(&src_path, &dest_path)?;
        } else {
            std::fs::copy(&src_path, &dest_path)?;
        }
    }
    Ok(excluded)
}

/// Copies a node folder to a temporary working directory.
///
/// Returns the path to the temporary directory and the list of top-level
/// directories that were excluded from the copy. The caller is responsible
/// for cleaning up the temporary directory.
pub fn copy_node_to_temp_dir(
    from_dir: &Path,
    tmp_root: &Path,
) -> std::io::Result<(PathBuf, Vec<String>)> {
    std::fs::create_dir_all(tmp_root)?;
    let temp_dir = tempfile::TempDir::new_in(tmp_root)?;

    debug!(
        "Copying node folder from {} to temp dir {}",
        from_dir.display(),
        temp_dir.path().display()
    );

    let mut excluded = copy_dir_recursive(from_dir, temp_dir.path())?;
    excluded.sort();

    // Only persist the temp directory after a successful copy so that
    // failures clean up automatically via TempDir's Drop.
    let kept_path = temp_dir.keep();

    Ok((kept_path, excluded))
}

/// Copies the staged tree of a node, whole, into a new temporary directory
/// under `tmp_root`, which is removed when the returned guard drops: the tree
/// a build for another platform restages and builds, while the staged tree
/// itself goes to the build for this machine.
///
/// A staged tree holds no symlink (the add copies none, and a container
/// node's vendored crates are copies), so every entry is a directory or a
/// file, copied with its permissions.
pub fn copy_staged_tree(staged_dir: &Path, tmp_root: &Path) -> std::io::Result<tempfile::TempDir> {
    std::fs::create_dir_all(tmp_root)?;
    let copy = tempfile::TempDir::new_in(tmp_root)?;
    copy_whole_tree(staged_dir, copy.path())?;
    Ok(copy)
}

fn copy_whole_tree(src: &Path, dest: &Path) -> std::io::Result<()> {
    std::fs::create_dir_all(dest)?;
    for entry in std::fs::read_dir(src)? {
        let entry = entry?;
        let src_path = entry.path();
        let dest_path = dest.join(entry.file_name());
        let file_type = entry.file_type()?;
        if file_type.is_dir() {
            copy_whole_tree(&src_path, &dest_path)?;
        } else if file_type.is_file() {
            std::fs::copy(&src_path, &dest_path)?;
        } else {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                format!(
                    "{} is neither a file nor a directory, which a staged tree does not hold",
                    src_path.display()
                ),
            ));
        }
    }
    Ok(())
}

/// Verifies that the node directory is in sync with the currently running daemon
/// by comparing the stored git hash with the expected one.
///
/// Returns `Ok(())` if verification passes, or `Err(error_message)` if it fails.
pub fn verify_git_hash(source_path: &Path, expected_git_hash: &str) -> Result<(), String> {
    let git_hash_path = source_path.join(PEPPY_OUTPUT_DIR).join("git.hash");
    let stored_git_hash = std::fs::read_to_string(&git_hash_path).map_err(|e| {
        format!(
            "Missing required git hash file at {}: {}. Run `peppy node sync` before `peppy node add`.",
            git_hash_path.display(),
            e
        )
    })?;

    let expected_git_hash = expected_git_hash.trim();
    let stored_git_hash = stored_git_hash.trim();

    if stored_git_hash.is_empty() {
        return Err(format!(
            "Invalid git hash file at {}: file is empty. Run `peppy node sync` before `peppy node add`.",
            git_hash_path.display(),
        ));
    }

    if stored_git_hash != expected_git_hash {
        return Err(format!(
            "git hash mismatch for node directory {} (expected '{}', found '{}' in {}). Run `peppy node sync` before retrying.",
            source_path.display(),
            expected_git_hash,
            stored_git_hash,
            git_hash_path.display(),
        ));
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    #[test]
    fn is_excluded_dir_rejects_known_dirs() {
        for name in [
            ".peppy",
            ".venv",
            "node_modules",
            "target",
            ".git",
            "build",
            "__pycache__",
        ] {
            assert!(
                is_excluded_dir(std::ffi::OsStr::new(name)),
                "expected {name:?} to be excluded"
            );
        }
    }

    #[test]
    fn is_excluded_dir_accepts_normal_dirs() {
        for name in ["src", "lib", "data", "scripts", "peppy", "my_module"] {
            assert!(
                !is_excluded_dir(std::ffi::OsStr::new(name)),
                "expected {name:?} to be allowed"
            );
        }
    }

    #[test]
    fn a_staged_tree_is_copied_whole_with_its_permissions() {
        use std::os::unix::fs::PermissionsExt as _;
        let staged = tempfile::tempdir().unwrap();
        fs::create_dir_all(staged.path().join(".peppy/libs/peppylib")).unwrap();
        fs::write(staged.path().join(".peppy/libs/peppylib/x.so"), b"so").unwrap();
        fs::write(staged.path().join("run.sh"), b"#!/bin/sh").unwrap();
        fs::set_permissions(
            staged.path().join("run.sh"),
            fs::Permissions::from_mode(0o755),
        )
        .unwrap();
        fs::create_dir_all(staged.path().join("empty")).unwrap();
        let tmp_root = tempfile::tempdir().unwrap();

        let copy = copy_staged_tree(staged.path(), tmp_root.path()).unwrap();

        assert_eq!(
            fs::read(copy.path().join(".peppy/libs/peppylib/x.so")).unwrap(),
            b"so"
        );
        let mode = fs::metadata(copy.path().join("run.sh"))
            .unwrap()
            .permissions()
            .mode();
        assert_eq!(mode & 0o111, 0o111);
        assert!(copy.path().join("empty").is_dir());
        let copied = copy.path().to_path_buf();
        drop(copy);
        assert!(!copied.exists(), "the copy goes with its guard");
    }

    #[test]
    fn copy_dir_recursive_excludes_and_copies() {
        let src = tempfile::tempdir().expect("tempdir");
        let dest = tempfile::tempdir().expect("tempdir");

        // Create included and excluded dirs/files
        fs::create_dir(src.path().join("src")).unwrap();
        fs::write(src.path().join("src/main.rs"), "fn main() {}").unwrap();
        fs::write(src.path().join("peppy.json5"), "{}").unwrap();
        fs::create_dir(src.path().join("target")).unwrap();
        fs::write(src.path().join("target/debug"), "binary").unwrap();
        fs::create_dir(src.path().join(".git")).unwrap();
        fs::write(src.path().join(".git/HEAD"), "ref").unwrap();

        let excluded = copy_dir_recursive(src.path(), dest.path()).expect("copy should succeed");

        assert!(excluded.contains(&"target".to_string()));
        assert!(excluded.contains(&".git".to_string()));
        assert!(dest.path().join("src/main.rs").exists());
        assert!(dest.path().join("peppy.json5").exists());
        assert!(!dest.path().join("target").exists());
        assert!(!dest.path().join(".git").exists());
    }

    #[test]
    fn copy_dir_recursive_skips_symlinks() {
        let src = tempfile::tempdir().expect("tempdir");
        let dest = tempfile::tempdir().expect("tempdir");

        fs::write(src.path().join("real.txt"), "content").unwrap();
        #[cfg(unix)]
        {
            std::os::unix::fs::symlink(src.path().join("real.txt"), src.path().join("link.txt"))
                .unwrap();
        }

        copy_dir_recursive(src.path(), dest.path()).expect("copy should succeed");

        assert!(dest.path().join("real.txt").exists());
        #[cfg(unix)]
        assert!(!dest.path().join("link.txt").exists());
    }

    #[test]
    fn copy_node_to_temp_dir_creates_temp_and_copies() {
        let src = tempfile::tempdir().expect("tempdir");
        let tmp_root = tempfile::tempdir().expect("tempdir");

        fs::write(src.path().join("peppy.json5"), "{}").unwrap();
        fs::create_dir(src.path().join(".venv")).unwrap();

        let (working_dir, excluded) =
            copy_node_to_temp_dir(src.path(), tmp_root.path()).expect("copy should succeed");

        assert!(working_dir.join("peppy.json5").exists());
        assert!(!working_dir.join(".venv").exists());
        assert!(excluded.contains(&".venv".to_string()));

        // Clean up the kept tempdir
        let _ = fs::remove_dir_all(&working_dir);
    }

    #[test]
    fn verify_git_hash_succeeds_on_match() {
        let dir = tempfile::tempdir().expect("tempdir");
        let peppy_dir = dir.path().join(PEPPY_OUTPUT_DIR);
        fs::create_dir_all(&peppy_dir).unwrap();
        fs::write(peppy_dir.join("git.hash"), "abc123\n").unwrap();

        verify_git_hash(dir.path(), "abc123").unwrap();
    }

    #[test]
    fn verify_git_hash_fails_on_mismatch() {
        let dir = tempfile::tempdir().expect("tempdir");
        let peppy_dir = dir.path().join(PEPPY_OUTPUT_DIR);
        fs::create_dir_all(&peppy_dir).unwrap();
        fs::write(peppy_dir.join("git.hash"), "abc123").unwrap();

        let err = verify_git_hash(dir.path(), "def456").unwrap_err();
        assert!(err.contains("git hash mismatch"), "got: {err}");
    }

    #[test]
    fn verify_git_hash_fails_on_empty() {
        let dir = tempfile::tempdir().expect("tempdir");
        let peppy_dir = dir.path().join(PEPPY_OUTPUT_DIR);
        fs::create_dir_all(&peppy_dir).unwrap();
        fs::write(peppy_dir.join("git.hash"), "  \n").unwrap();

        let err = verify_git_hash(dir.path(), "abc123").unwrap_err();
        assert!(err.contains("file is empty"), "got: {err}");
    }

    #[test]
    fn verify_git_hash_fails_on_missing_file() {
        let dir = tempfile::tempdir().expect("tempdir");

        let err = verify_git_hash(dir.path(), "abc123").unwrap_err();
        assert!(err.contains("Missing required git hash file"), "got: {err}");
    }
}
